from __future__ import annotations

from pydantic import Field
from typing_extensions import TypedDict

from ..core import SdkBaseModel
from .enums.cause11 import Cause11OrStr


class StartTimerFailedEventAttributes(SdkBaseModel):
    timer_id: str = Field(alias="timerId")
    """The timerId provided in the StartTimer decision that failed."""

    cause: Cause11OrStr
    """The cause of the failure. This information is generated by the system and can be useful for diagnostic purposes.
    If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it lacked sufficient permissions. For
    details and example IAM policies, see Using IAM to Manage Access to Amazon SWF Workflows in the Amazon SWF Developer
    Guide."""

    decision_task_completed_event_id: int = Field(alias="decisionTaskCompletedEventId")
    """The ID of the DecisionTaskCompleted event corresponding to the decision task that resulted in the StartTimer
    decision for this activity task. This information can be useful for diagnosing problems by tracing back the chain of
    events leading up to this event."""


class StartTimerFailedEventAttributesDict(TypedDict):
    timer_id: str
    cause: Cause11OrStr
    decision_task_completed_event_id: int
